def tee(iterable, n=2):
    it = iter(iterable)
    queues = [[] for _ in range(n)]
    def gen(q):
        while True:
            if not q:
                try:
                    val = next(it)
                    for other_q in queues:
                        other_q.append(val)
                except StopIteration:
                    return
            yield q.pop(0)
    return [gen(q) for q in queues]
gens = tee([1,2,3])
print([list(g) for g in gens])

