def merge_sorted(a, b):
    ia, ib = iter(a), iter(b)
    va, vb = next(ia, None), next(ib, None)
    while va is not None or vb is not None:
        if va is not None and (vb is None or va <= vb):
            yield va
            va = next(ia, None)
        else:
            yield vb
            vb = next(ib, None)
